  laws: [
    { f: 'C = ε₀ A / d', name: 'سعة المتسعة ذات الصفيحتين المتوازيتين (هواء أو فراغ)', read: 'السعة تساوي سماحية الفراغ في المساحة المتقابلة مقسومة على البعد بين الصفيحتين', vars: [['ε₀', 'سماحية الفراغ = 8.85 × 10⁻¹²', 'C²/N·m²'], ['A', 'المساحة السطحية المتقابلة لكل صفيحة', 'm²'], ['d', 'البعد بين الصفيحتين', 'm']], when: 'إذا أُعطيت أبعاد المتسعة وطُلبت سعتها.', note: 'حوّل cm² إلى m² بالضرب في 10⁻⁴، و mm إلى m بالضرب في 10⁻³. مساحة الصفيحة المربعة = مربع طول ضلعها.' },
    { f: 'C_k = k ε₀ A / d', name: 'سعة المتسعة بوجود عازل', read: 'السعة بوجود العازل تساوي ثابت العزل في سماحية الفراغ في المساحة مقسومة على البعد', vars: [['k', 'ثابت العزل', 'بلا وحدات']], when: 'إذا ملأ العازل الحيز بين الصفيحتين.', note: 'C ∝ A و C ∝ 1/d و C ∝ k. استعملها للمقارنة بالنسب دون حساب كامل.' }
  ],
  reasons: [
    { q: 'وضح كيف يتغير مقدار سعة متسعة ذات صفيحتين متوازيتين (الهواء عازل بينهما) بتغير المساحة السطحية للصفيحتين، مع ذكر العلاقة الرياضية. (س4 a)', a: 'تتناسب السعة طرديًا مع المساحة المتقابلة C ∝ A، حسب العلاقة C = ε₀A/d. فزيادة المساحة تزيد السعة، ونقصانها يقللها.' },
    { q: 'وضح كيف يتغير مقدار السعة بتغير البعد بين الصفيحتين، مع ذكر العلاقة الرياضية. (س4 b)', a: 'تتناسب السعة عكسيًا مع البعد C ∝ 1/d حسب C = ε₀A/d. فتقريب الصفيحتين يزيد السعة، وإبعادهما يقللها.' },
    { q: 'وضح كيف يتغير مقدار السعة بتغير نوع الوسط العازل، مع ذكر العلاقة الرياضية. (س4 c)', a: 'تزداد السعة بالعامل k (ثابت عزل المادة): C_k = kε₀A/d = kC.' },
    { q: 'علل: عند إزاحة إحدى صفيحتي متسعة مشحونة ومفصولة جانبًا تزداد قراءة الفولطميتر المربوط بين صفيحتيها.', a: 'لأن المساحة المتقابلة تقل فتقل السعة (C ∝ A)، والشحنة ثابتة، فيزداد فرق الجهد حسب ΔV = Q/C.' },
    { q: 'علل: تُصنع صفائح المتسعات شرائح رقيقة واسعة تلف بشكل أسطواني مع عازل رقيق ذي ثابت عزل كبير.', a: 'لزيادة السعة بالتحكم بالعوامل الثلاثة: مساحة كبيرة (C ∝ A)، وبعد صغير جدًا بين الصفيحتين (C ∝ 1/d)، وثابت عزل كبير (C ∝ k)، مع حجم صغير بسبب اللف.' }
  ],
