    { q: 'متسعة هوائية مربعة الصفيحتين طول الضلع 10 cm والبعد 0.5 cm. مساحة الصفيحة بالمتر المربع:', o: ['1 × 10⁻² m²', '1 × 10⁻¹ m²', '100 m²', '5 × 10⁻³ m²'], c: 0, why: 'A = (0.1)² = 0.01 m².' }
